 /* Acné */
 ["a1","acne","¿Qué bacteria prolifera en el folículo obstruido en el acné?",["Cutibacterium acnes","Staphylococcus aureus","Corynebacterium"],"Crece en el ambiente sin oxígeno del folículo y genera inflamación."],
 ["a2","acne","¿Qué es un comedón abierto?",["Un «punto negro» por oxidación del contenido del poro","Un bulto blanquecino por acumulación de sebo y células","Una lesión roja e inflamada sin pus"],"El bulto blanquecino es el comedón cerrado; la lesión roja sin pus, la pápula."],
 ["a3","acne","¿Qué lesiones definen el acné moderado?",["Pápulas y pústulas","Comedones y seborrea","Nódulos y quistes"],"Leve: comedones y seborrea. Grave: nódulos y quistes."],
 ["a4","acne","¿Qué ingrediente para el acné se destaca como apto en el embarazo?",["El ácido azelaico","El ácido salicílico","Los retinoides"],"Además es antiinflamatorio y despigmentante."],
 ["a5","acne","Al empezar con retinoides o salicílico, el acné empeora un poco. ¿Qué haces?",["Explicar que es el «efecto purga» y seguir, salvo irritación intensa","Suspender el tratamiento y pasar a un retinoide más suave","Añadir un exfoliante físico para acelerar la limpieza del poro"],"Es normal un empeoramiento inicial."],
 ["a26","acne","¿Qué estructura de la piel se altera en el acné?",["La unidad pilosebácea","La glándula sudorípara apocrina","El estrato córneo"],"Se obstruye el folículo y, a menudo, se inflama."],
 ["a27","acne","¿Por qué hay exceso de sebo en el acné?",["Por los andrógenos, aunque la analítica hormonal sea normal","Por estrógenos elevados, que se ven en la analítica","Por un déficit de vitamina A y de zinc en la dieta"],"Es uno de los cuatro mecanismos principales."],
 ["a28","acne","¿Qué es la hiperqueratinización en el acné?",["La acumulación de células del folículo que forma un tapón","La oxidación del contenido del poro que lo oscurece","La proliferación de bacterias dentro del folículo cerrado"],"La oxidación es lo que da el punto negro."],
 ["a29","acne","¿Cómo es el acné de la mujer adulta?",["Lesiones inflamatorias en mandíbula y cuello, de origen hormonal","Seborrea con lesiones en zona T, pecho y espalda, muy frecuente","Lesiones inflamatorias monomorfas, sin comedones, por fármacos"],"La segunda opción describe el acné adolescente y la tercera, el acné por medicamentos."],
 ["a30","acne","¿Qué causa el acné mecánico?",["El roce o la oclusión (mochilas, cascos, mascarillas)","Los productos comedogénicos o aceites capilares","El contacto con sustancias químicas en el trabajo"],"La segunda opción es el acné por cosméticos y la tercera, el profesional."],
 ["a31","acne","¿Qué hace el gluconato de zinc en el acné?",["Inhibe la 5-alfa reductasa","Actúa como antibacteriano, igual que el regaliz","Matifica, como las arcillas"],"Es uno de los ingredientes útiles del acné."],
 ["a32","acne","¿Qué efecto tiene el sol sobre el acné?",["Puede empeorarlo: más sebo, más inflamación y marcas más oscuras","Mejora la inflamación, aunque oscurece las marcas que deja","No le afecta si se usa un protector oil-free de textura gel"],"La exposición solar no mejora el acné."],
 ["a33","acne","¿Cuál de estos es un error frecuente en el acné?",["Aplicar los productos solo sobre los granos visibles","Usar una hidratante ligera no comedogénica","Usar un gel syndet por la mañana"],"Las otras dos opciones forman parte de la rutina recomendada."],
 /* Dermatitis atópica */
 ["a6","atopica","¿Qué proteína está disminuida en la piel atópica?",["La filagrina","La queratina dura","La elastina"],"La filagrina es esencial para la estructura y la hidratación de la piel."],
 ["a7","atopica","Tras la ducha, ¿cuándo se aplica la crema emoliente en la piel atópica?",["En los primeros 5 minutos","A los 15–30 minutos","Antes de la ducha, para proteger la piel"],"15–30 minutos es lo que se espera tras el tratamiento médico en un brote."],
 ["a8","atopica","¿Qué forma cosmética se indica en zonas engrosadas y liquenificadas?",["Las pomadas","Las cremas y bálsamos","Las lociones"],"Cremas y bálsamos: mantenimiento. Lociones: lesiones exudativas y cuero cabelludo."],
 ["a9","atopica","¿Cómo deben ser las duchas en la dermatitis atópica?",["Cortas (menos de 10 minutos), 2–3 veces por semana, con agua tibia","Diarias, de menos de 10 minutos, con agua templada y un syndet","Largas, 2–3 veces por semana, con agua tibia y aceite en el agua"],"Y secando con toalla suave sin frotar."],
 ["a34","atopica","¿Qué es la dermatitis atópica?",["Una enfermedad inflamatoria crónica con brotes, de origen inmunológico","Una dermatitis alérgica de contacto causada por cosméticos irritantes","Una infección crónica por Staphylococcus aureus con brotes de picor"],"Influyen factores genéticos, ambientales y emocionales."],
 ["a35","atopica","¿Con qué otras afecciones se asocia con frecuencia la dermatitis atópica?",["Rinitis, asma o dermatitis de contacto","Rosácea y acné","Dermatitis seborreica y psoriasis"],"Suele empezar en los primeros meses de vida."],
 ["a36","atopica","¿Cómo son las lesiones de dermatitis atópica en los lactantes?",["En mejillas, frente, cuero cabelludo y tronco, muy exudativas","En pliegues de codos y rodillas, secas y descamativas","En rostro, cuello y pliegues, con liquenificación"],"La segunda opción describe la infancia y la tercera, adolescentes y adultos."],
 ["a37","atopica","¿Qué es la liquenificación?",["Placas engrosadas y rugosas por rascado crónico","Pápulas que desaparecen por rascado dejando costras","Zonas rojas con vesículas, exudado y costras"],"La segunda opción es el prurigo y la tercera, el eccema."],
 ["a38","atopica","¿A qué bacteria es más vulnerable la piel atópica?",["Staphylococcus aureus","Cutibacterium acnes","Corynebacterium"],"También a virus como el herpes y a hongos como Candida o Malassezia."],
 ["a39","atopica","Durante un brote, ¿cómo se combinan el tratamiento médico y el cosmético?",["Primero el médico, y a los 15–30 minutos el cosmético","Primero el cosmético, y a los 5 minutos el médico","Los dos a la vez, mezclados en la mano"],"Así no se interfiere con el tratamiento."],
 ["a40","atopica","¿Qué ingredientes hay que evitar en la piel atópica?",["Retinoides, AHAs y despigmentantes irritantes","Niacinamida, bakuchiol y ácido tranexámico","Avena, aloe vera y agua termal"],"Para manchas o arrugas se prefieren niacinamida, tranexámico o bakuchiol."],
 ["a41","atopica","¿Qué tejidos se recomienda evitar en la dermatitis atópica?",["La lana y las fibras sintéticas","El algodón y el lino","La seda y el algodón orgánico"],"También la sudoración excesiva y los cambios bruscos de temperatura."],
 /* Oncología */
 ["a10","oncologia","En una zona irradiada, ¿cuándo NO deben aplicarse los cosméticos?",["En las 4 horas previas a la sesión de radioterapia","En las 2 horas posteriores a cada sesión de radioterapia","En las 24 horas previas a la sesión de radioterapia"],"Se aplican dos veces al día, nunca en las cuatro horas previas."],
 ["a11","oncologia","Si un paciente oncológico necesita depilarse, ¿qué método se recomienda?",["La maquinilla eléctrica","La cuchilla con gel","La cera tibia"],"Se evitan cera, cuchilla y cremas depilatorias."],
 ["a42","oncologia","¿Cuál es la alteración cutánea más frecuente durante el tratamiento oncológico?",["La sequedad extrema","Las erupciones acneiformes","La fotosensibilidad"],"Las tres pueden aparecer, pero la más frecuente es la sequedad extrema."],
 ["a43","oncologia","¿Qué productos se recomiendan para la piel del paciente oncológico?",["Productos para piel sensible, aunque no indiquen «oncológico»","Solo productos con indicación específica para pacientes oncológicos","Productos seborreguladores, porque aparecen erupciones acneiformes"],"El cuidado es muy similar al de la piel atópica."],
 ["a44","oncologia","¿Qué ingrediente se recomienda en zonas irradiadas?",["El sucralfato","El ácido hialurónico hidrolizado","El ácido salicílico"],"También centella asiática, sulfato de zinc y aloe vera puro."],
 ["a45","oncologia","¿Cuándo se puede volver a teñir el cabello?",["Al terminar la quimioterapia, cuando el cabello recupere su fortaleza","Durante el tratamiento, siempre que el tinte no lleve amoníaco","Entre un ciclo y otro de quimioterapia, cuando la piel esté tranquila"],"Tampoco se usan anticaída sin indicación médica."],
 ["a46","oncologia","¿Cómo se recomienda secar el cabello durante el tratamiento?",["Al aire, evitando el calor","Con secador a temperatura baja","Frotando con toalla para acortar el tiempo"],"Y lavarlo según necesidad con un champú suave."],
 ["a47","oncologia","¿Qué es la onicolisis?",["La separación parcial de la uña de su lecho","La inflamación de los laterales de la uña","La aparición de estrías en la uña"],"La inflamación de los laterales es la paroniquia."],
 ["a48","oncologia","¿Qué se evita en el cuidado facial durante el tratamiento?",["Exfoliantes y limpiezas faciales profesionales","Hidratar por la mañana y por la noche","Limpiadores syndet y mascarillas hidratantes"],"Tampoco retinoides, AHAs ni despigmentantes irritantes."],
 ["a49","oncologia","¿A qué radiación da más fotosensibilidad el tratamiento oncológico?",["A la UVA","A la UVB","A la luz visible"],"Hay que usar FPS 50+ de amplio espectro a diario."],
 ["a50","oncologia","¿Cómo suelen ser las reacciones cutáneas del tratamiento oncológico?",["Reversibles al terminar el tratamiento","Permanentes en uñas y cabello","Permanentes en la pigmentación de la piel"],"Aunque son molestas y afectan a la calidad de vida."],
 ["a51","oncologia","¿Qué se recomienda para los labios durante el tratamiento?",["Usar reparador labial a diario","Usar bálsamo solo si aparecen grietas","Exfoliarlos una vez por semana"],"Forma parte del cuidado facial recomendado."],
 /* Pigmentación */
 ["a12","pigmentacion","¿Cuál es la enzima clave en la producción de melanina?",["La tirosinasa","La metaloproteinasa","La ciclooxigenasa"],"Puede activarse o inhibirse, dando más o menos pigmentación."],
 ["a13","pigmentacion","¿Qué pasa cuando en el melasma la melanina se deposita en la dermis?",["El color se vuelve grisáceo y los cosméticos funcionan peor","El color se vuelve marrón oscuro y los cosméticos funcionan mejor","El color se vuelve rosado y responde a los calmantes"],"Cuanto más profundo el pigmento, menor eficacia."],
 ["a14","pigmentacion","¿Qué protector solar se recomienda en problemas de pigmentación?",["De muy alta protección y preferiblemente con color","De muy alta protección, transparente y mineral","De alta protección (FPS 30) con antioxidantes"],"El color ayuda a bloquear la luz visible, que también empeora las manchas."],
 ["a52","pigmentacion","¿Cómo se llama el proceso por el que los melanocitos producen melanina?",["Melanogénesis","Queratinización","Glicación"],"La queratinización forma queratina; la glicación se relaciona con el envejecimiento."],
 ["a53","pigmentacion","Una persona adulta consulta por una mancha nueva que ha cambiado. ¿Qué haces?",["Recomendar que la vea el dermatólogo para descartar malignidad","Recomendar un despigmentante durante 3 meses","Recomendar fotoprotección y vigilarla unas semanas"],"Ante manchas nuevas o que cambian, siempre dermatólogo."],
 ["a54","pigmentacion","¿Cómo son los léntigos solares?",["Manchas planas en zonas expuestas, por acumulación de melanosomas","Manchas pequeñas que aparecen en la infancia en fototipo I","Manchas difusas de origen hormonal en frente y mejillas"],"La segunda opción son las efélides y la tercera, el melasma."],
 ["a55","pigmentacion","¿Cómo son los léntigos simples?",["Benignos, no relacionados con el sol y no cambian con las estaciones","Benignos, relacionados con el sol y se intensifican en verano","Aparecen tras un proceso inflamatorio y tardan meses en irse"],"Pueden aparecer en cualquier zona del cuerpo."],
 ["a56","pigmentacion","¿Qué son las efélides?",["Las pecas: aparecen en la infancia en piel clara y se intensifican con el sol","Manchas planas por exposición solar crónica que aumentan con la edad","Manchas que aparecen tras un proceso inflamatorio"],"Suelen atenuarse con la edad."],
 ["a57","pigmentacion","¿Cuál es el origen del melasma?",["Hormonal y agravado por el sol; más frecuente en mujeres de fototipo alto","Postinflamatorio; más frecuente en pieles oscuras tras acné o rascado","Solar crónico; más frecuente con la edad en rostro, escote y manos"],"La segunda opción es la HPI y la tercera, los léntigos solares."],
 ["a58","pigmentacion","¿En qué pieles es más frecuente la hiperpigmentación postinflamatoria?",["En pieles oscuras","En pieles de fototipo I","En embarazadas"],"Puede tardar meses en desaparecer."],
 ["a59","pigmentacion","¿Qué efecto tienen los cosméticos en los léntigos solares o simples?",["Limitado: lo más importante es la fotoprotección","Muy bueno con retinoides","Bueno con inhibidores de la transferencia de melanosomas"],"Los despigmentantes funcionan mejor en pecas, melasma y HPI."],
 ["a60","pigmentacion","¿Qué ingredientes son útiles en las manchas por lipofuscina?",["Los que activan el proteosoma, como Delentigo™","Los inhibidores de la tirosinasa","Los AHA en peeling dos noches por semana"],"Son las llamadas manchas de la edad."],
 ["a61","pigmentacion","¿Cuándo hay que evitar iniciar tratamientos despigmentantes irritantes?",["En verano","En invierno","Durante la primera semana de tratamiento"],"En meses de sol se mantiene un tratamiento suave para evitar recaídas."],
 /* Envejecimiento */
 ["a15","envejecimiento","¿Qué son las arrugas estáticas?",["Las que se ven incluso en reposo","Las que se ven al gesticular","Las relacionadas con la oxidación y la glicación"],"Dinámicas: al gesticular. Metabólicas: oxidación y glicación."],
 ["a16","envejecimiento","¿Qué forma la base de la pirámide del proaging?",["La protección: fotoprotector, antioxidantes y antipolución","La renovación: retinoides y AHAs o PHAs","La activación: péptidos y factores de crecimiento"],"La renovación es la zona media y la activación, la cúspide."],
 ["a17","envejecimiento","Según Glogau, ¿cómo es el grupo 3?",["Avanzado (45–60 años): arrugas visibles en reposo y flacidez","Moderado (30–45 años): arrugas en movimiento y cambios pigmentarios","Severo (+60 años): arrugas generalizadas y piel amarillenta"],"El grupo 3 sube ya a FPS 50."],
 ["a62","envejecimiento","¿Cuáles son los dos componentes del envejecimiento cutáneo?",["Crono-envejecimiento y fotoenvejecimiento","Envejecimiento intrínseco y hormonal","Envejecimiento epidérmico y dérmico"],"Lo epidérmico y lo dérmico son niveles donde se manifiesta, no componentes."],
 ["a63","envejecimiento","¿Qué radiaciones son especialmente dañinas para el envejecimiento?",["La UVA y la infrarroja (IR-A)","La UVB y la luz azul","La UVB y la infrarroja (IR-A)"],"Estimulan enzimas que degradan colágeno y elastina."],
 ["a64","envejecimiento","¿Con qué se relacionan las arrugas metabólicas?",["Con la oxidación y la glicación","Con la radiación ultravioleta","Con el gesto repetido de la cara"],"Las causadas por UV son las fotoinducidas."],
 ["a65","envejecimiento","¿Qué alteraciones vasculares aparecen con la edad?",["Cuperosis, arañas vasculares y ojeras azuladas","Telangiectasias, flushing y rinofima","Manchas, léntigos y piel amarillenta"],"El rinofima es de la rosácea fimatosa."],
 ["a66","envejecimiento","¿Qué hay en la zona media de la pirámide del proaging?",["La renovación: retinoides de nueva generación y AHAs o PHAs","La protección: fotoprotector y antioxidantes","La activación: péptidos y células madre vegetales"],"Base: protección. Cúspide: activación y regeneración."],
 ["a67","envejecimiento","¿Para qué se usa la carnosina?",["Como antiglicación","Como anti-inflammaging","Como antioxidante enzimático"],"Anti-inflammaging: extracto de magnolia. Antioxidante enzimático: superóxido dismutasa."],
 ["a68","envejecimiento","¿Qué rutina de mañana corresponde al grupo 1 de Glogau?",["Antioxidantes, hidratación y FPS 30+","Antioxidantes, hidratación, proaging y FPS 50","Hidratación y retinoides de baja concentración"],"Los grupos 3 y 4 añaden proaging y FPS 50."],
 ["a69","envejecimiento","¿Por qué se aplican de noche los retinoides y exfoliantes?",["Porque de noche la piel se regenera y son más eficaces","Porque por la mañana la piel absorbe menos los activos","Para que no interfieran con el maquillaje durante el día"],"Por la mañana la piel necesita protección y antioxidantes."],
 ["a70","envejecimiento","¿Cómo es el grupo 1 de Glogau?",["Leve (20–30 años): líneas finas, sin arrugas profundas","Leve (30–45 años): arrugas solo al gesticular","Moderado (20–30 años): líneas finas y manchas"],"El grupo 2 (30–45) ya tiene arrugas en movimiento."],
 ["a71","envejecimiento","¿Cómo se introducen los activos antiedad?",["Con el método de transiciones, de forma progresiva","Todos a la vez, empezando a baja concentración","Alternando un activo distinto cada mes"],"La rutina se adapta al grado de envejecimiento y la tolerancia."],
 /* Rosácea */
 ["a18","rosacea","¿En qué se diferencia la rosácea pápulo-pustular del acné?",["No presenta comedones ni suele dejar cicatrices","No presenta pústulas ni suele dejar cicatrices","Presenta comedones, pero no inflamación"],"Tiene pápulas y pústulas centrofaciales."],
 ["a19","rosacea","¿De qué color es el corrector que neutraliza las rojeces?",["Verde","Amarillo","Lila"],"Después, maquillaje apto para piel sensible con filtros UV."],
 ["a20","rosacea","¿Qué ácaro del microbioma se relaciona con la rosácea?",["Demodex folliculorum","Malassezia","Helicobacter pylori"],"Malassezia es un hongo y H. pylori una bacteria (también relacionada)."],
 ["a72","rosacea","¿En quién predomina la rosácea?",["En mujeres de piel clara","En mujeres de fototipo alto","En hombres de piel clara"],"El melasma es el que es más frecuente en fototipos altos."],
 ["a73","rosacea","¿Qué es el flushing?",["Un rubor súbito con sensación de calor","Un enrojecimiento persistente","Unos capilares visibles en la piel"],"El enrojecimiento persistente es el eritema; los capilares visibles, telangiectasias."],
 ["a74","rosacea","¿Dónde se localizan las lesiones de la rosácea?",["En la zona centrofacial, respetando el contorno de ojos","En la zona centrofacial, incluidos los párpados","En mejillas, cuello y escote"],"Cuello y escote son localizaciones poco frecuentes."],
 ["a75","rosacea","¿Qué es el rinofima?",["La rosácea fimatosa de la nariz","La rosácea pápulo-pustular de la nariz","La rosácea eritemato-telangiectásica de la nariz"],"Es un engrosamiento por hipertrofia de las glándulas sebáceas."],
 ["a76","rosacea","¿Cuál de estos es un desencadenante de la rosácea?",["El uso prolongado de corticoides tópicos","El ácido azelaico en pápulas y pústulas","Los filtros solares físicos minerales"],"Azelaico y filtros físicos se recomiendan en la rosácea."],
 ["a77","rosacea","¿Qué ingrediente es de los más eficaces y mejor tolerados para pápulas y pústulas?",["El ácido azelaico","El ácido salicílico","La gluconolactona"],"El salicílico se usa en piel grasa sin brote; la gluconolactona, para renovar sin irritar."],
 ["a78","rosacea","¿Qué protector solar se recomienda en la rosácea?",["Amplio espectro, FPS 30 o más, con siliconas y filtros físicos","FPS 50 con filtros químicos ligeros y alcohol para refrescar","FPS 15 con color, suficiente si se usa corrector verde"],"Dióxido de titanio u óxido de zinc."],
 ["a79","rosacea","Si en la rosácea no se tolera el agua, ¿cómo se limpia la piel?",["Con solución micelar o emulsión limpiadora","Con agua termal templada y algodón","Con un gel limpiador suave con espuma"],"Se evitan dispositivos de limpieza y exfoliantes agresivos."],
 ["a80","rosacea","¿Qué síntomas da la rosácea ocular?",["Ojos rojos, sensación de arenilla e inflamación de párpados","Engrosamiento de los párpados por glándulas sebáceas","Pápulas y pústulas en los párpados"],"Puede afectar a la conjuntiva o a la córnea."],
 ["a81","rosacea","¿Cómo se aplican las brumas de agua termal en la rosácea?",["En frío","A temperatura ambiente","Templadas, para relajar los vasos"],"El frío calma la piel; el calor es un desencadenante."],
 /* Dermatitis seborreica */
 ["a21","seborreica","¿Qué hongo se relaciona con la dermatitis seborreica?",["Malassezia","Candida","Demodex"],"Demodex es un ácaro, relacionado con la rosácea."],
 ["a22","seborreica","¿Qué es la costra láctea?",["La dermatitis seborreica infantil","La dermatitis atópica del lactante","El acné neonatal"],"Placas amarillentas y grasas en la fontanela."],
 ["a23","seborreica","¿Cómo es el mantenimiento en la dermatitis seborreica del cuero cabelludo?",["Champú antifúngico dos veces por semana, alternando con uno suave","Champú antifúngico cada 2–3 días de forma indefinida","Champú antifúngico una vez por semana, sin alternar"],"Cada 2–3 días es la frecuencia del tratamiento, no del mantenimiento."],
 ["a82","seborreica","¿Qué es la dermatitis seborreica?",["Una enfermedad inflamatoria crónica con descamación grasa amarillenta","Una enfermedad inflamatoria crónica con sequedad intensa y picor","Una infección contagiosa por Malassezia"],"Afecta a zonas ricas en glándulas sebáceas."],
 ["a83","seborreica","Un cliente con dermatitis seborreica cree que tiene la piel seca por las escamas. ¿Qué le explicas?",["Que es un exceso de sebo combinado con inflamación","Que es una falta de lípidos en la barrera","Que es una deshidratación temporal de la piel"],"Muchas personas lo confunden con piel seca."],
 ["a84","seborreica","¿En quién es más frecuente la dermatitis seborreica?",["En hombres y en personas inmunodeprimidas","En mujeres adultas y embarazadas","En adolescentes con acné"],"Aparece tanto en lactantes como en adultos."],
 ["a85","seborreica","¿Cuál de estos ingredientes es antifúngico?",["La piroctona olamina","La enoxolona","La keluamida"],"La enoxolona es calmante; la keluamida, calmante y queratolítica."],
 ["a86","seborreica","¿Cuál de estos ingredientes es queratolítico?",["La urea","El climbazol","El própolis"],"El climbazol es antifúngico y el própolis, seborregulador."],
 ["a87","seborreica","¿Cómo influyen las estaciones en la dermatitis seborreica?",["En invierno empeoran cara y cuero cabelludo; en verano, los pliegues","En verano empeoran cara y cuero cabelludo; en invierno, los pliegues","En invierno empeoran todas las zonas por igual"],"Es una patología con brotes recurrentes."],
 ["a88","seborreica","¿Cómo se aplica el champú de tratamiento?",["Dos aplicaciones; la segunda se deja actuar unos minutos","Una sola aplicación, dejándola actuar 10 minutos","Dos aplicaciones, aclarando enseguida cada una"],"Así mejora su eficacia."],
 ["a89","seborreica","¿Con qué frecuencia se usa el champú de tratamiento?",["Cada 2–3 días","A diario","Una vez por semana"],"Después se pasa a mantenimiento dos veces por semana."],
 ["a90","seborreica","¿Qué texturas se prefieren en la dermatitis seborreica?",["Gel o cremagel","Cremas ricas","Bálsamos"],"Hay que evitar cosméticos grasos u oclusivos y el alcohol en las fórmulas."],
 ["a91","seborreica","¿Qué zonas del rostro afecta típicamente?",["Cejas, entrecejo, pliegues nasogenianos y aletas nasales","Mejillas, mentón y contorno de ojos, respetando la nariz","Contorno de labios, párpado inferior y cuello"],"También pabellones auriculares y borde de la frente."],
 /* Celulitis */
 ["a24","celulitis","En la celulitis de grado 2, ¿cuándo se ve la piel de naranja?",["Al estar de pie","Solo al pellizcar","En cualquier posición"],"Grado 1: al pellizcar. Grado 3: en cualquier posición."],
 ["a25","celulitis","¿Qué tipo de celulitis presenta signo de Godet positivo?",["La edematosa o acuosa","La blanda o flácida","La compacta o dura"],"Cursa con retención de líquidos y pesadez."],
 ["a92","celulitis","¿Qué capa de la piel altera la celulitis?",["La hipodermis","La dermis","La epidermis"],"Por problemas de microcirculación, retención de líquidos y cambios en el colágeno."],
 ["a93","celulitis","¿Cómo es la celulitis en los hombres?",["Menos frecuente y en zonas más altas del cuerpo","Igual de frecuente, en muslos y glúteos","Menos frecuente, en muslos y rodillas"],"Por la mayor firmeza de su piel."],
 ["a94","celulitis","¿Cómo es la celulitis de grado 4?",["Nódulos visibles, palpables y dolorosos; requiere valoración médica","Visible en cualquier posición, con ondulaciones y posible dolor","Visible al estar de pie, con problemas circulatorios"],"La segunda opción es el grado 3 y la tercera, el grado 2."],
 ["a95","celulitis","¿Cómo es la celulitis compacta o dura?",["Piel firme, visible solo al pellizcar; típica de jóvenes con buen tono","Piel de naranja visible a simple vista, con flacidez y varices","Piel fina, con pesadez, dolor y signo de Godet positivo"],"La segunda opción es la blanda y la tercera, la edematosa."],
 ["a96","celulitis","¿Cómo es la celulitis blanda o flácida?",["Visible a simple vista, con flacidez; común a partir de los 30–40 años","Firme, visible solo al pellizcar; frecuente en jóvenes deportistas","Con pesadez, dolor y piel fina; afecta sobre todo a piernas y rodillas"],"Se asocia a varices, retención y cambios bruscos de peso."],
 ["a97","celulitis","¿Cuál de estos ingredientes tiene acción lipolítica?",["La cafeína","El castaño de indias","El mentol"],"El castaño de indias mejora la circulación; el mentol es rubefaciente."],
 ["a98","celulitis","¿Qué hacen los ingredientes rubefacientes?",["Activan la microcirculación","Inhiben la lipogénesis","Reestructuran el tejido"],"Ejemplos: mentol, alcanfor, nicotinato y salicilato de metilo."],
 ["a99","celulitis","¿Cuál es la pauta de un anticelulítico?",["Dos veces al día durante 3 meses y después una vez al día todo el año","Una vez al día durante 3 meses y después descansar otros 3 meses","Dos veces al día solo en los 3 meses previos al verano"],"La constancia es clave."],
 ["a100","celulitis","¿Cómo se hace el masaje al aplicar el anticelulítico?",["Ascendente, desde la rodilla al muslo","Descendente, desde el muslo a la rodilla","Circular, sin dirección fija"],"Mejora la circulación y la penetración del producto."],
 ["a101","celulitis","¿Qué se recomienda en la celulitis blanda o mixta?",["Reafirmante por la mañana y lipolítico por la noche","Lipolítico una o dos veces al día, sin reafirmante","Drenante y tonificante por la mañana y por la noche"],"Lipolítico 1–2 veces al día es para la compacta; drenante, para la edematosa."],
 ["a102","celulitis","¿Qué tratamiento médico-estético complementa la celulitis blanda?",["La radiofrecuencia","La presoterapia","La ultracavitación"],"Presoterapia: edematosa y compacta. Ultracavitación: compacta."]
